// internal/lowlevel: callers outside the generated package hold the
// returned value by inference (raw := b.Raw()) and chain its
// methods, but cannot name the type in their own signatures.
func (inst *ExampleEntityBuilder) Raw() *lowlevel.InEntityAuditexampleTable {
	if err := inst.buf.MarkRaw(); err != nil {
		inst.store.dml.AppendError(err)
	}
	inst.raw = true // direct DML writes cannot be mirrored into the entity
	return inst.store.dml
}

// Entity is the entity as the typed Add* calls built it so far, as Commit
// mirrors it to the cache views: what a writer digests or forwards without
// reading the row back. mirrored is false after Raw(), when the entity does
// not have everything the row will.
func (inst *ExampleEntityBuilder) Entity() (ent ExampleEntity, mirrored bool) {
	return inst.ent, !inst.raw
}

// Commit finishes the open entity, buffers the row, and writes it
// through to attached cache views: the entity is populated and pinned
// until the store's Flush makes it durable — reads after writes hit
// immediately, and the caching version gate plus the pin make a raced
// refetch of the pre-write row bounce off. A commit that touched
// Raw() cannot be materialized faithfully and invalidates the key
// instead. A failed Commit rolls the frame back — the entity is
// discarded and the store stays usable.
func (inst *ExampleEntityBuilder) Commit() (err error) {
	if ferr := inst.buf.Flush(inst.endSection); ferr != nil {
		inst.store.dml.AppendError(ferr) // surfaced by CommitEntity below
	}
	inst.buf.Reset()
	err = lowlevel.InEntityAuditexampleTableCommitEntity(inst.store.dml)
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed) // release Begin's ambient stamps (consumed by the closed attributes)
	if err != nil {
		_ = lowlevel.InEntityAuditexampleTableRollbackEntity(inst.store.dml) // no-op error when no frame is open
		return
	}
	inst.store.buffered++
	inst.store.dirty[inst.key] = struct{}{}
	if inst.raw {
		inst.store.notifyWrite(inst.key, nil)
	} else {
		ent := inst.ent
		inst.store.notifyWrite(inst.key, &ent)
	}
	inst.store.noteCommitted(recordstore.WrittenKey[uint64, time.Time]{Key: inst.key, Order: inst.ent.Ts, Lifecycle: recordstore.LifecycleLive, Tombstone: false, Identity: inst.ident})
	return
}

// Rollback abandons the open entity frame without committing it;
// already-buffered rows and the store remain usable.
func (inst *ExampleEntityBuilder) Rollback() (err error) {
	inst.buf.Reset() // the buffered contributions are abandoned with the frame
	inst.store.dml.PopMembershipsHighCardRef(inst.pushed)
	return lowlevel.InEntityAuditexampleTableRollbackEntity(inst.store.dml)
}

// IngestOrigin buffers one whole entity per row carrying only the
// Origin component, all stamped with ts — rows ship on the next Flush,
// like every write. The envelope carries the pass-through columns
// the row binds; the others are written zero — use Begin with a
// filled envelope to set them. Keys must be distinct within one call (rows
// share ts, so duplicates would tie on Order): a duplicate returns
// recordstore.ErrDuplicateIngestKey. On any error the rows buffered
// so far remain buffered — Flush ships them, DiscardPending drops
// them.
func (inst *ExampleStore) IngestOrigin(ts time.Time, rows []Origin) (err error) {
	return inst.IngestOriginCtx(context.Background(), ts, rows)
}

// IngestOriginCtx is IngestOrigin with the context BeginCtx hands the
// configured stampers.
func (inst *ExampleStore) IngestOriginCtx(ctx context.Context, ts time.Time, rows []Origin) (err error) {
	seen := make(map[uint64]struct{}, len(rows))
	for i := range rows {
		if _, dup := seen[rows[i].Id]; dup {
			err = eh.Errorf("ingest origin row %d: %w: key %v", i, recordstore.ErrDuplicateIngestKey, rows[i].Id)
			return
		}
		seen[rows[i].Id] = struct{}{}
		err = inst.BeginCtx(ctx, rows[i].Id, ts, ExampleEnvelope{}).AddOrigin(rows[i]).Commit()
		if err != nil {
			err = eh.Errorf("ingest origin row %d: %w", i, err)
			return
		}
	}
	return
}

