// --- decode (Arrow → entity bags). ---

// auditexampleSectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type auditexampleSectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *ExampleStore) queryEntities(ctx context.Context, sql string) (ents []*ExampleEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeExampleRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *ExampleStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*ExampleEntity, error] {
	return func(yield func(*ExampleEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// decodeExampleRecord reads one fetched Arrow record into entity bags:
// envelope from the plain readers, components via presence-gated,
// membership-matched reads (fat rows carry optional components — the
// kind-homogeneous helpers cannot decode them).
func decodeExampleRecord(rec arrow.RecordBatch) (ents []*ExampleEntity, err error) {
	idR := lowlevel.NewReadAccessAuditexampleTablePlainEntityIdAttributes()
	tsR := lowlevel.NewReadAccessAuditexampleTablePlainEntityTimestampAttributes()
	symbolR := lowlevel.NewReadAccessAuditexampleTableTaggedSymbol()
	u64ArrayR := lowlevel.NewReadAccessAuditexampleTableTaggedU64Array()
	stringArrayR := lowlevel.NewReadAccessAuditexampleTableTaggedStringArray()
	readers := []auditexampleSectionReaderI{idR, tsR, symbolR, u64ArrayR, stringArrayR}
	for _, r := range readers {
		err = r.LoadFromRecord(rec)
		if err != nil {
			err = eh.Errorf("load auditexample reader from record: %w", err)
			return
		}
	}
	defer func() {
		for _, r := range readers {
			r.Release()
		}
	}()

	n := idR.ValueId.Len()
	tsType, ok := tsR.ValueTs.DataType().(*arrow.TimestampType)
	if !ok {
		err = eh.Errorf("order column is not a timestamp (got %s)", tsR.ValueTs.DataType())
		return
	}
	ents = make([]*ExampleEntity, 0, n)
	for i := range n {
		ent := &ExampleEntity{
			ID: idR.ValueId.Value(i),
			Ts: tsR.ValueTs.Value(i).ToTime(tsType.Unit).UTC(),
		}
		ent.NaturalKey = idR.GetAttrValueNaturalKey(raruntime.EntityIdx(i))
		{
			row, ok, e := originReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read origin component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				ent.Origin = option.Some(row)
			}
		}
		{
			row, ok, e := auditEventReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), stringArrayR.GetAttributes(), stringArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read auditEvent component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				ent.AuditEvent = option.Some(row)
			}
		}
		{
			row, ok, e := evidenceSealReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), stringArrayR.GetAttributes(), stringArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read evidenceSeal component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				ent.EvidenceSeal = option.Some(row)
			}
		}
		ents = append(ents, ent)
	}
	return
}
